from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class CounterInfoPMV1(SchemaObject):
    id = SchemaField(name="id")
    name = SchemaField(name="name")
    abbreviation = SchemaField(name="abbreviation")
    description = SchemaField(name="description")
    unit = SchemaField(name="unit")

    def __init__(self, id, name, abbreviation, description, unit):
        self.id = id
        self.name = name
        self.abbreviation = abbreviation
        self.description = description
        self.unit = unit
        super(CounterInfoPMV1, self).__init__()
